function validate([s, t, k]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 2) return 's needs at least 2 characters.';
  if (t.length !== s.length) return 's and t must have the same length.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase letters.';
  if (!Number.isInteger(k) || k < 1 || k > 1e15) return 'k is an integer from 1 to 10^15.';
  return null;
}

