  const MOD = 1000000007n;
  const n = s.length;
  const fail = new Array(n).fill(0);
  let len = 0;
  for (let i = 1; i < n; i++) {
    while (len > 0 && t[i] !== t[len]) len = fail[len - 1];
    if (t[i] === t[len]) len++;
    fail[i] = len;
  }
  const text = s + s.slice(0, n - 1);
  let sameAsStart = 0n;
  let otherMatches = 0n;
  len = 0;
  for (let i = 0; i < text.length; i++) {
    while (len > 0 && text[i] !== t[len]) len = fail[len - 1];
    if (text[i] === t[len]) len++;
    if (len === n) {
      if (i === n - 1) sameAsStart = 1n;
      else otherMatches++;
      len = fail[len - 1];
    }
  }
  const multiply = (a, b) => [
    (a[0] * b[0] + a[1] * b[2]) % MOD,
    (a[0] * b[1] + a[1] * b[3]) % MOD,
    (a[2] * b[0] + a[3] * b[2]) % MOD,
    (a[2] * b[1] + a[3] * b[3]) % MOD
  ];
  let result = [1n, 0n, 0n, 1n];
  let step = [0n, BigInt(n - 1), 1n, BigInt(n - 2)];
  let power = k;
  while (power > 0) {
    if (power % 2 === 1) result = multiply(result, step);
    step = multiply(step, step);
    power = Math.floor(power / 2);
  }
  const atStart = result[0];
  const atOther = result[2];
  return Number((sameAsStart * atStart + otherMatches * atOther) % MOD);
