function numberOfWays(s, t, k) {
  const MOD = 1000000007n;
  const n = s.length;
  // ways[o] counts the sequences that leave s rotated left by o.
  const combine = (a, b) => {
    const out = new Array(n).fill(0n);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) out[(i + j) % n] = (out[(i + j) % n] + a[i] * b[j]) % MOD;
    return out;
  };
  // Moving the last l characters to the front is a left rotation by n - l.
  let single = new Array(n).fill(0n);
  for (let l = 1; l < n; l++) single[n - l] += 1n;
  let ways = new Array(n).fill(0n);
  ways[0] = 1n;
  let left = k;
  while (left > 0) {
    if (left % 2 === 1) ways = combine(ways, single);
    single = combine(single, single);
    left = Math.floor(left / 2);
  }
  let total = 0n;
  for (let o = 0; o < n; o++) if (s.slice(o) + s.slice(0, o) === t) total += ways[o];
  return Number(total % MOD);
}

