function generate(rand, size) {
  const pick = (alphabet) => alphabet[Math.floor(rand() * alphabet.length)];
  const word = (length, alphabet) => Array.from({ length }, () => pick(alphabet)).join('');
  let s;
  if (size === 'large') {
    const period = 1 + Math.floor(rand() * 20);
    const base = word(period, rand() < 0.5 ? 'ab' : 'xyz');
    s = base.repeat(Math.floor(10000 / period));
  } else {
    const n = 2 + Math.floor(rand() * 6);
    const alphabet = rand() < 0.5 ? 'ab' : 'abc';
    if (rand() < 0.35) {
      const period = 1 + Math.floor(rand() * 3);
      s = word(period, alphabet).repeat(n).slice(0, n);
    } else s = word(n, alphabet);
  }
  const n = s.length;
  let t;
  if (rand() < 0.75) {
    const shift = Math.floor(rand() * n);
    t = s.slice(shift) + s.slice(0, shift);
  } else t = word(n, size === 'large' ? 'abxyz' : 'abc');
  const k = size === 'large' || rand() < 0.3 ? 1 + Math.floor(rand() * 1e15) : 1 + Math.floor(rand() * 8);
  return [s, t, k];
}
